import { z } from 'zod';
import { COMMUNITIES, EVENT_TYPE_IDS } from '../constants/event-types.js';
import { LANGUAGE_CODES } from '../constants/languages.js';
import { slugSchema, webUrl } from './common.js';
import { designDocSchema, type DesignDoc } from '../design/schema.js';

const text = (max: number) => z.string().trim().max(max);

/** The words printed on the invite. Generated by AI, always editable by the user. */
export const eventContentSchema = z.object({
  invocation: text(140).optional(),
  headline: text(80).default(''),
  hostLine: text(320).optional(),
  primaryNames: z.array(text(60)).max(2).default([]),
  primaryDetails: z.array(text(160)).max(2).default([]),
  connector: text(24).optional(),
  message: text(700).optional(),
  familyTitle: text(60).optional(),
  familyLines: z.array(text(140)).max(16).default([]),
  closing: text(240).optional(),
  /** "Swagatotsuk" / "Darshanabhilashi": relatives eagerly awaiting the guests. */
  welcomeTitle: text(60).optional(),
  welcomeLines: z.array(text(140)).max(16).optional(),
  /** "With best compliments from". */
  complimentsTitle: text(60).optional(),
  complimentsLines: z.array(text(140)).max(12).optional(),
  /** Printed on the card's RSVP block (the website has its own RSVP form). */
  rsvpContacts: z.array(z.object({ name: text(60), phone: text(24) })).max(3).optional(),
  /** Free note, e.g. "Your blessings are our gift". */
  note: text(240).optional(),
  hashtag: text(40).optional(),
});
export type EventContent = z.infer<typeof eventContentSchema>;

export const eventFunctionInputSchema = z.object({
  id: z.uuid().optional(),
  name: text(60).min(1),
  startsAt: z.iso.datetime({ offset: true }),
  endsAt: z.iso.datetime({ offset: true }).optional(),
  venueName: text(120).min(1),
  venueAddress: text(300).optional(),
  mapUrl: webUrl().optional(),
  dressCode: text(80).optional(),
  notes: text(300).optional(),
});
export type EventFunctionInput = z.infer<typeof eventFunctionInputSchema>;

/** Automatic follow-ups. `auto` sends through WhatsApp Business (paid plan); otherwise they wait in the host's send queue. */
export const followUpsSchema = z.object({
  auto: z.boolean().default(false),
  /** Remind guests who have not opened the invite this many days after it was sent (0 = off). */
  unopenedDays: z.number().int().min(0).max(30).default(3),
  /** Ask for an RSVP this many days before the first function (0 = off). */
  rsvpDaysBefore: z.number().int().min(0).max(60).default(7),
  /** Day-before message with venue and map. */
  dayBefore: z.boolean().default(true),
  /** Thank-you after the event, linking to the album. */
  thanks: z.boolean().default(true),
});
export type FollowUps = z.infer<typeof followUpsSchema>;

export const eventSettingsSchema = z.object({
  timezone: z.string().default('Asia/Kolkata'),
  rsvpEnabled: z.boolean().default(true),
  rsvpDeadline: z.iso.datetime({ offset: true }).optional(),
  askMealPreference: z.boolean().default(false),
  askAccommodation: z.boolean().default(false),
  showCountdown: z.boolean().default(true),
  musicTrackId: z.string().max(64).optional(),
  photoAssetIds: z.array(z.uuid()).max(6).default([]),
  galleryAssetIds: z.array(z.uuid()).max(30).default([]),
  backgroundAssetId: z.uuid().optional(),
  aiClipAssetId: z.uuid().optional(),
  followUps: followUpsSchema.optional(),
  /** Save-the-date mode: the site shows only names, date and city until the full invite is released. */
  saveTheDate: z.boolean().default(false),
});
export type EventSettings = z.infer<typeof eventSettingsSchema>;

export const createEventSchema = z.object({
  type: z.enum(EVENT_TYPE_IDS),
  language: z.enum(LANGUAGE_CODES),
  secondaryLanguage: z.enum(LANGUAGE_CODES).optional(),
  community: z.enum(COMMUNITIES).optional(),
  templateId: z.string().min(3).max(64),
  title: text(120).min(1),
  content: eventContentSchema,
  functions: z.array(eventFunctionInputSchema).min(1).max(12),
  settings: eventSettingsSchema.partial().optional(),
  /** Card design made in the editor before saving (optional). */
  design: designDocSchema.optional(),
});
export type CreateEventInput = z.infer<typeof createEventSchema>;

/**
 * PATCH semantics for settings: no defaults (Zod 4 would otherwise fill them in and wipe saved
 * values), omitted = unchanged, `null` = clear the field.
 */
export const eventSettingsPatchSchema = z.object({
  timezone: z.string().optional(),
  rsvpEnabled: z.boolean().optional(),
  rsvpDeadline: z.iso.datetime({ offset: true }).nullable().optional(),
  askMealPreference: z.boolean().optional(),
  askAccommodation: z.boolean().optional(),
  showCountdown: z.boolean().optional(),
  musicTrackId: z.string().max(64).nullable().optional(),
  photoAssetIds: z.array(z.uuid()).max(6).optional(),
  galleryAssetIds: z.array(z.uuid()).max(30).optional(),
  backgroundAssetId: z.uuid().nullable().optional(),
  aiClipAssetId: z.uuid().nullable().optional(),
  followUps: followUpsSchema.nullable().optional(),
  saveTheDate: z.boolean().optional(),
});
export type EventSettingsPatch = z.infer<typeof eventSettingsPatchSchema>;

/** Applies a settings patch on top of saved settings. */
export function mergeSettings(current: EventSettings, patch: EventSettingsPatch): EventSettings {
  const next: Record<string, unknown> = { ...current };
  for (const [k, v] of Object.entries(patch)) {
    if (v === null) delete next[k];
    else if (v !== undefined) next[k] = v;
  }
  return eventSettingsSchema.parse(next);
}

/** Editor autosave. `null` resets to the template's automatic layout. */
export const saveDesignSchema = z.object({ design: designDocSchema.nullable() });
export type SaveDesignInput = z.infer<typeof saveDesignSchema>;

export const updateEventSchema = createEventSchema.omit({ design: true }).partial().extend({
  slug: slugSchema.optional(),
  settings: eventSettingsPatchSchema.optional(),
});
export type UpdateEventInput = z.infer<typeof updateEventSchema>;

export const EVENT_STATUSES = ['draft', 'published', 'archived'] as const;
export type EventStatus = (typeof EVENT_STATUSES)[number];

export interface EventFunctionDto extends EventFunctionInput {
  id: string;
  sortOrder: number;
}

export interface EventDto {
  id: string;
  slug: string;
  status: EventStatus;
  type: (typeof EVENT_TYPE_IDS)[number];
  language: (typeof LANGUAGE_CODES)[number];
  secondaryLanguage: (typeof LANGUAGE_CODES)[number] | null;
  community: (typeof COMMUNITIES)[number] | null;
  templateId: string;
  title: string;
  content: EventContent;
  settings: EventSettings;
  design: DesignDoc | null;
  functions: EventFunctionDto[];
  features: string[];
  credits: Record<string, number>;
  viewCount: number;
  /** What the signed-in person may do: `owner` or a co-host role. */
  access: 'owner' | 'editor' | 'guests' | 'viewer';
  createdAt: string;
  updatedAt: string;
}
